import InputText from 'primevue/inputtext';
import Select from 'primevue/select';

export default {
    name: "Detail",
    data() {
      return {
        size: [
          { name: 'XS', code: 'XS' },
          { name: 'S', code: 'S' },
          { name: 'M', code: 'M' },
          { name: 'L', code: 'L' },
          { name: 'XL', code: 'XL' },
          { name: 'XXL', code: 'XXL' },
        ]
      };
    },
    components: {
      InputText,
      Select
    }
  };
